#include <bits/stdc++.h>
using namespace std;

#define N 200010

int main() {
	int n;
	int p[N];

	bool pr[N];
	int mu[N];
	vector<int>m;
	vector<int>d[N];

	bool used[N];
	vector<int>cand;
	long long num[N];

	long long ans = 0;

	cin >> n;
	for (int i = 0; i < n; i++)cin >> p[i + 1];

	for (int i = 1; i <= n; i++) {
		pr[i] = true;
		mu[i] = -1;
	}
	pr[1] = false;
	mu[1] = 0;

	for (int i = 2; i <= n; i++) {
		if (pr[i]) {
			mu[i] = -mu[i];
			for (int j = 2; (i*j) <= n; j++) {
				pr[i*j] = false;
				if (j%i == 0)mu[i*j] = 0;
				else mu[i*j] = -mu[i*j];
			}
		}
		if (mu[i] != 0) {
			m.push_back(i);
			for (int j = i; j <= n; j += i)d[j].push_back(i);
		}
	}

	for (int i = 1; i <= n; i++) {
		used[i] = false;
		num[i] = 0;
	}
	for (auto &a : m) {
		for (int i = a; i <= n; i += a) {
			for (auto &j : d[p[i]]) {
				num[j]++;
				if (!used[j]) {
					used[j] = true;
					cand.push_back(j);
				}
			}
		}
		for (auto &b : cand) {
			ans += mu[a] * mu[b] * ((num[b] * (num[b] + 1)) / 2);
			num[b] = 0;
			used[b] = false;
		}
		cand.clear();
	}

	cout << ans << endl;


	return 0;
}
